import java.util.*;import java.util.jar.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import static org.objectweb.asm.Opcodes.*;
/** Independent inverse of every pre-existing method; constructor-tail comparison uses separate normalization. */
public final class StaticReplacementDelta {
 static final String P="local/lito381/server/",H=P+"NativeStaticCancellationReplacement",C=P+"NativeCancellationNpcStatic",S=P+"NativeStaticNpcScene",M=P+"NativeStaticNpcMotion",POP=P+"ClassicWorldMonsterPopulation",ACT=POP+"$Actor";
 static ClassNode read(JarFile j,String n)throws Exception{var c=new ClassNode();new ClassReader(j.getInputStream(j.getJarEntry(n+".class"))).accept(c,ClassReader.SKIP_DEBUG|ClassReader.SKIP_FRAMES);return c;}
 static AbstractInsnNode prev(AbstractInsnNode n){do{n=n.getPrevious();}while(n!=null&&n.getOpcode()<0);return n;}
 static AbstractInsnNode next(AbstractInsnNode n){do{n=n.getNext();}while(n!=null&&n.getOpcode()<0);return n;}
 static byte[] body(ClassNode c,MethodNode m,String name){var t=new ClassNode();t.version=c.version;t.access=c.access;t.name=c.name;t.superName=c.superName;var copy=new MethodNode(m.access,name,m.desc,m.signature,m.exceptions.toArray(String[]::new));m.accept(copy);t.methods.add(copy);var w=new ClassWriter(ClassWriter.COMPUTE_MAXS);t.accept(w);return w.toByteArray();}
 static void removeBefore(MethodNode m,AbstractInsnNode call,int n){for(int k=0;k<n;k++)m.instructions.remove(prev(call));}
 static void inverse(String cls,MethodNode m){for(var n:m.instructions.toArray())if(n instanceof MethodInsnNode call&&call.owner.equals(H)){
  if(cls.equals(C)){if(call.name.equals("routeType")||call.name.equals("admissionTarget")){call.owner=P+"NativeCancellationNpcRules$Rule";call.name=call.name.equals("routeType")?"type":"targetId";call.desc="()I";call.setOpcode(INVOKEVIRTUAL);}else if(call.name.equals("apply"))call.owner=P+"NativeCancellationNpcTransform";else throw new AssertionError("unreviewed static port");}
  else if(cls.equals(S)&&call.name.equals("prunable")){removeBefore(m,call,1);m.instructions.remove(call);}
  else if(cls.equals(M)){switch(call.name){case"all"->{removeBefore(m,call,2);call.owner=P+"ClassicWorldNpcCatalog";call.desc="(I)Ljava/util/List;";}case"dialog"->{call.owner=P+"ClientSession";call.name="nativeStaticOriginalDialog";call.desc="(J)V";call.setOpcode(INVOKEVIRTUAL);}case"visible"->{removeBefore(m,call,1);m.instructions.remove(call);}case"frame","poseLive"->{int loads=call.name.equals("frame")?3:2;removeBefore(m,call,loads);var branch=next(call);var ret=next(branch);if(!(branch instanceof JumpInsnNode)||ret.getOpcode()!=RETURN)throw new AssertionError("bounded retirement entry gate");m.instructions.remove(branch);m.instructions.remove(ret);m.instructions.remove(call);}default->throw new AssertionError("unreviewed motion port");}}
  else throw new AssertionError("unreviewed class port");
 }}
 static String instruction(AbstractInsnNode n,boolean old){String out=""+n.getOpcode();if(n instanceof VarInsnNode v){int var=v.var;if(old)var=switch(var){case 0,1->var;case 4->6;case 6->7;case 8->9;case 9->10;case 10->11;default->throw new AssertionError("unmapped constructor local "+var);};out+=":"+var;}else if(n instanceof FieldInsnNode v)out+=":"+v.owner+":"+v.name+":"+v.desc;else if(n instanceof MethodInsnNode v)out+=":"+v.owner+":"+v.name+":"+v.desc;else if(n instanceof TypeInsnNode v)out+=":"+v.desc;else if(n instanceof LdcInsnNode v)out+=":"+v.cst;else if(n instanceof IntInsnNode v)out+=":"+v.operand;else if(n instanceof JumpInsnNode||n instanceof InvokeDynamicInsnNode||n instanceof IincInsnNode)throw new AssertionError("unexpected constructor tail instruction");return out;}
 static AbstractInsnNode tail(MethodNode m){for(var n:m.instructions)if(n instanceof TypeInsnNode t&&t.desc.equals(P+"ClassicWorldMonsterCatalog$SpawnDefinition")){var store=prev(n);var field=prev(store);var load=prev(field);if(!(field instanceof FieldInsnNode f)||!f.name.equals("nextQuestDynamicObjectId")||!(store instanceof VarInsnNode)||load.getOpcode()!=ALOAD)throw new AssertionError("original constructor-tail boundary");return load;}throw new AssertionError("missing allocation");}
 static void constructor(ClassNode old,ClassNode changed){var a=old.methods.stream().filter(m->m.name.equals("nativeCancellationSpawn")).findFirst().orElseThrow();var b=changed.methods.stream().filter(m->m.name.equals("nativeStaticCancellationSpawn")).findFirst().orElseThrow();var expected=new ArrayList<String>();int substitutions=0;for(var n=tail(a);n!=null;n=n.getNext()){
  if(n.getOpcode()<0)continue;if(n instanceof VarInsnNode v&&v.getOpcode()==ALOAD&&v.var==5){var field=(FieldInsnNode)next(n);int parameter=switch(field.name){case"x"->3;case"y"->4;case"heading"->5;case"definition"->2;default->throw new AssertionError("source anchor field");};n=field;if(parameter==2){var id=next(n);if(!(id instanceof MethodInsnNode m)||!m.name.equals("spawnId"))throw new AssertionError("source spawn identity");n=id;}expected.add(ILOAD+":"+parameter);substitutions++;}else expected.add(instruction(n,true));
 }var actual=new ArrayList<String>();for(var n=tail(b);n!=null;n=n.getNext())if(n.getOpcode()>=0)actual.add(instruction(n,false));if(substitutions!=9||!expected.equals(actual))throw new AssertionError("original native constructor/pose/occupancy/registration/id instruction tail differs");}
 public static void main(String[]args)throws Exception{try(var base=new JarFile(args[0]);var jar=new JarFile(args[1])){var changed=new HashSet<String>();var prior=new HashSet<String>();for(var e:Collections.list(base.entries())){prior.add(e.getName());var current=jar.getJarEntry(e.getName());if(current==null)throw new AssertionError("removed archive entry");if(!Arrays.equals(base.getInputStream(e).readAllBytes(),jar.getInputStream(current).readAllBytes()))changed.add(e.getName());}var fresh=new HashSet<String>();for(var e:Collections.list(jar.entries()))if(!prior.contains(e.getName()))fresh.add(e.getName());var names=Set.of(C,S,S+"$Actor",M,M+"$Motion",POP);if(!changed.equals(names.stream().map(n->n+".class").collect(java.util.stream.Collectors.toSet()))||!fresh.equals(Set.of(H+".class",H+"$Allocation.class",H+"$Retired.class")))throw new AssertionError("archive boundary");
 for(var name:names){var a=read(base,name);var b=read(jar,name);int addedFields=name.equals(S+"$Actor")||name.equals(M+"$Motion")?1:0,addedMethods=name.equals(C)||name.equals(POP)?1:name.equals(M)?2:0;if(b.fields.size()!=a.fields.size()+addedFields||b.methods.size()!=a.methods.size()+addedMethods)throw new AssertionError("schema boundary "+name);for(int k=0;k<a.fields.size();k++){var x=a.fields.get(k);var y=b.fields.get(k);if(x.access!=y.access||!x.name.equals(y.name)||!x.desc.equals(y.desc)||!Objects.equals(x.value,y.value))throw new AssertionError("original field changed");}if(addedFields!=0){var f=b.fields.get(b.fields.size()-1);if(!f.name.equals("nativeStaticCancellationRetired")||!f.desc.equals("Z")||f.access!=ACC_VOLATILE)throw new AssertionError("bounded retirement field");}if(name.equals(POP))constructor(a,b);
  for(var original:a.methods){String renamed=name.equals(C)&&original.name.equals("route")?"nativeStaticReplacementOriginalRoute":name.equals(M)&&original.name.equals("touch")?"nativeStaticReplacementOriginalTouch":name.equals(M)&&original.name.equals("talk")?"nativeStaticReplacementOriginalTalk":original.name;var m=b.methods.stream().filter(v->v.name.equals(renamed)&&v.desc.equals(original.desc)).findFirst().orElseThrow();inverse(name,m);if(!Arrays.equals(body(a,original,original.name),body(b,m,original.name)))throw new AssertionError("original method changed "+name+"."+original.name+original.desc);}
 }
 for(var name:List.of(H,H+"$Allocation",H+"$Retired")){var c=read(jar,name);for(var f:c.fields)if((f.access&ACC_STATIC)!=0&&(!f.desc.equals("Ljava/lang/String;")||f.value==null))throw new AssertionError("static actor state");for(var m:c.methods)for(var n:m.instructions)if(n instanceof MethodInsnNode call&&(call.owner.startsWith("java/sql/")||call.owner.startsWith("java/nio/file/")||call.owner.contains("Executor")||call.owner.contains("GameStateStore")))throw new AssertionError("new persistence or worker");}
 }System.out.println("PASS independent archive/method inverse and exact original native constructor-tail instructions; no PC entry changed");}
}
